import {viewModel as calculate,viewEngineering as engineering} from './view-model.mjs';
import {sensitivity} from './model.mjs';
import {campus,layout,electrical,cooling,chartCash} from './drawings.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=v=>typeof v==='string'?v:Array.isArray(v)?v.map(text).join(' • '):v&&typeof v==='object'?Object.entries(v).map(([k,x])=>`${k}: ${text(x)}`).join('; '):String(v??'');
const E=v=>esc(text(v));
const q=new URLSearchParams(location.search);let region=['alberta','texas'].includes(q.get('project'))?q.get('project'):'alberta';let section=q.get('view')||'overview';let drawing='layout';let projects={};let edits={alberta:{},texas:{}};const views=[['overview','Development case'],['site','Site & power'],['engineering','Engineering'],['economics','Economics'],['delivery','Delivery & commercial'],['evidence','Evidence & downloads']];
if(!views.some(x=>x[0]===section))section='overview';
const number=(v,d=1)=>Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
let P,M,ENG;
const money=(v,d=0)=>`${P.currency} ${number(v,d)}m`;
const refs=ids=>(ids||[]).map(id=>`<a class="source-ref" href="?project=${region}&view=evidence#${esc(id)}" data-source="${esc(id)}">[${esc(id)}]</a>`).join('');
const ul=arr=>`<ul class="clean-list">${(arr||[]).map(x=>`<li>${E(x)}</li>`).join('')}</ul>`;
const heading=(n,t)=>`<div class="section-line"><h2>${t}</h2><span>${n}</span></div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const metric=(title,value,note)=>`<div class="metric"><small>${title}</small><strong>${value}</strong><span class="unit">${note}</span></div>`;
const download=(path,label)=>`<a class="action" href="downloads/${region}/${path}" download="${region}-${path}">${label} ↗</a>`;
function drawingBox(kind){let content={layout,electrical,cooling}[kind](P,ENG);return `<div class="drawing large"><div class="drawing-label"><span>${region.toUpperCase()} / ${kind.toUpperCase()} / REV 01</span><span>CONCEPT DESIGN</span></div>${content}<div class="drawing-footer">Design assumptions, not construction drawings. Equipment and geometry require professional validation.</div></div>`}
function hero(){return `<div class="hero-grid"><div><span class="badge"><i class="dot"></i>Independent development proposal</span><h1 class="hero-title">${E(P.id==='alberta'?'Alberta':'Texas')}<span>100 MW.</span></h1><p class="lede">${E(P.subtitle)}</p><div class="actions"><button class="action primary" data-view="engineering">Explore the design →</button>${download('dossier.pdf','Project report')}</div></div><figure class="hero-figure">${campus(P,ENG)}<figcaption class="figure-caption"><span>01 / FULL-BUILD CONCEPT</span><span>4 × 25 MW IT</span></figcaption></figure></div>`}
function overview(){return hero()+`<div class="metrics">${metric('Full-build IT capacity','100 MW','4 × 25 MW phases')}${metric('Concept development CAPEX',money(M.capex.totalM),'Local currency · excludes GPUs')}${metric('First phase operating assumption',`M${M.inputs.firstOperationMonth}`,'Conditional project clock')}${metric('Design site demand',`${number(ENG.designFacilityMw,0)} MW`,'Peak sizing assumption')}</div><div class="split wide-left"><div>${heading('01','The development decision')}<p class="lede">${E(P.thesis)}</p>${(P.executiveSummary||[]).map(x=>`<p>${E(x)}</p>`).join('')}</div><div class="panel highlight"><div class="eyebrow">Current investment stance</div><h3>${E(P.verdict)}</h3><p>Advance evidence and preliminary development only. Construction commitment depends on the project-specific gates below.</p><button class="action light" data-view="delivery">Inspect the gates →</button></div></div>${heading('02','What makes this project specific')}<div class="text-grid"><div class="panel"><h3>Place</h3><p>${E(P.site.name)}</p><p class="small">${E(P.site.landStatus)}</p></div><div class="panel"><h3>Power</h3><p>${E(P.power.strategy)}</p>${refs(P.power.sourceIds)}</div><div class="panel"><h3>Customer</h3><p>${E(P.commercial.customer)}</p></div></div>${heading('03','The conditions that stop development')}<ul class="clean-list numbered">${P.killCriteria.map(x=>`<li><span>${E(x)}</span></li>`).join('')}</ul><div class="callout"><b>Scope and maturity</b>This is a complete concept / pre-feasibility proposal for a facility development business. Land, permits, grid capacity, equipment slots, financing and customers are not secured. Financial estimates are editable planning assumptions; the site does not certify engineering or investment readiness.</div>`}
function site(){let s=P.site;return `<h1 class="page-title">A site is a set<br>of obligations.</h1><p class="lede">${E(s.name)} · ${E(s.municipality)}</p><div class="split wide-left"><div class="panel"><h3>Candidate location</h3>${[['Location',s.addressOrArea],['Land control',s.landStatus],['Concept land area',`${s.areaHa} ha`],['Map reference',`${s.lat}, ${s.lon}`],['Coordinate basis',s.coordinateBasis]].map(([a,b])=>`<div class="key-row"><span>${a}</span><span>${E(b)}</span></div>`).join('')}<div class="actions"><a class="action primary" target="_blank" rel="noopener" href="${esc(s.mapUrl)}">Open location map ↗</a></div>${refs(s.sourceIds)}</div><div><iframe class="map-frame" title="Candidate area reference map" loading="lazy" referrerpolicy="no-referrer" src="https://www.openstreetmap.org/export/embed.html?bbox=${s.lon-.045}%2C${s.lat-.03}%2C${s.lon+.045}%2C${s.lat+.03}&layer=mapnik&marker=${s.lat}%2C${s.lon}"></iframe><p class="small">Reference marker only. ${E(s.coordinateBasis)} © OpenStreetMap contributors.</p><div class="eyebrow">Selection rationale</div><p>${E(s.rationale)}</p>${ul(s.constraints)}</div></div>${heading('01','Screened alternatives')}${table(['Candidate','Assessment','Decision'],s.alternatives.map(x=>[E(x.name),E(x.reason),E(x.decision)]))}${heading('02','Power development pathway')}<div class="split"><div class="panel"><h3>Grid interface</h3><p>${E(P.power.gridRoute)}</p><p class="small">Utility / system interface: ${E(P.power.utility)}</p>${refs(P.power.sourceIds)}</div><div class="panel"><h3>Generation and resilience</h3><p>${E(P.power.generationRoute)}</p>${ul(P.power.constraints)}</div></div>${heading('03','Land, water and heat')}<div class="split"><div class="panel"><h3>Cooling strategy</h3><p>${E(P.cooling.strategy)}</p><p>${E(P.cooling.climateImplications)}</p></div><div class="panel"><h3>Water strategy</h3><p>${E(P.cooling.waterStrategy)}</p>${refs(P.cooling.sourceIds)}</div></div>${heading('04','Permissions and dependencies')}${table(['Approval / authority','Requirement','Sequence / assumed duration','Evidence'],P.permits.map(x=>[`<b>${E(x.name)}</b><br>${E(x.authority)}`,E(x.requirement),`${E(x.sequence)}<br><span class="pill">${E(x.assumedMonths)} months · ${E(x.status)}</span>`,refs(x.sourceIds)]))}`}
function engineeringView(){let e=ENG;return `<h1 class="page-title">From the grid<br>to the rack.</h1><p class="lede">Four repeatable 25 MW halls, a defined thermal path, and explicit redundancy assumptions. Annual PUE ${M.inputs.basePue}; design peak PUE ${M.inputs.peakPue??M.inputs.basePue}.</p><div class="metrics">${metric('IT rack assumption',`${e.racks.toLocaleString()} racks`,`${e.rackKw} kW per rack`)}${metric('Peak apparent demand',`${number(e.designMva,1)} MVA`,'Power factor 0.95')}${metric('UPS blocks',`${e.ups.totalUnits} × ${e.ups.unitMw} MW`,'Per hall: 5 duty + 1 reserve')}${metric('Loop circulation',`${number(e.cooling.liquidLoopFlowM3h,0)}`,'m³/h · IT liquid loop')}</div><div class="engineering-tabs" role="group" aria-label="Engineering drawing"><button data-drawing="layout" class="${drawing==='layout'?'active':''}">Campus layout</button><button data-drawing="electrical" class="${drawing==='electrical'?'active':''}">Electrical single-line</button><button data-drawing="cooling" class="${drawing==='cooling'?'active':''}">Cooling & water</button></div><div id="drawing">${drawingBox(drawing)}</div><div class="actions">${download('layout.svg','Layout SVG')}${download('electrical.svg','Single-line SVG')}${download('cooling.svg','Cooling SVG')}${download('engineering-basis.md','Design basis')}</div>${heading('01','Sizing and redundancy')}${table(['System','Concept basis','Validation required'],[['Primary transformers',`${e.primaryTransformers.installedUnits} × ${e.primaryTransformers.unitMva} MVA; N−1 capacity ${e.primaryTransformers.nMinusOneMva} MVA`,'Utility interface, impedance, fault duty and protection study'],['UPS',`${e.ups.totalUnits} × 5 MW; ${e.ups.batteryMinutes} minutes battery ride-through`,'IT load steps, transfer sequence, harmonics and battery end-of-life derating'],['Heat rejection',`${number(e.cooling.siteHeatRejectionMw)} MW; ${e.cooling.totalUnits} concept modules`,'OEM capacity at summer design dry bulb; glycol and fouling derating'],['IT liquid loop',`${e.cooling.liquidHeatMw} MW; ΔT ${e.cooling.deltaTC}°C; ${number(e.cooling.liquidLoopFlowLps)} L/s`,'Rack/CDU supply temperatures, water chemistry and pressure drop'],['Water make-up','Unquantified; dry-rejection concept has no cooling-tower assumption','Validate potable/process demand, leakage, optional adiabatic demand, firewater and generation water separately'],['Maintainability','N+1 components and sectionalized distribution concept','Failure-mode analysis, integrated systems testing and external certification']])}${heading('02','Equipment and procurement')}${table(['Package','Specification / quantity','Lead-time assumption','Status'],P.procurement.map(x=>[`<b>${E(x.package)}</b>`,`${E(x.specification)}<br>${E(x.quantity)}`,`${E(x.leadMonths)} months`,`${E(x.status)} ${refs(x.sourceIds)}`]))}${heading('03','Design qualifications')}${ul(e.notes||[])}<div class="callout"><b>Physical validation still required</b>Concept equipment counts and the campus rectangle are test-fit assumptions. A licensed multidisciplinary team must validate usable land, structural and fire codes, hydraulic/thermal performance, fault levels, geotechnical conditions, environmental effects and construction documents.</div>`}
const fields=[['leaseRateKwMonth','Lease / committed kW / month',50,400,.25,'$'],['occupancyPct','Leased capacity',0,100,5,'%'],['loadFactorPct','IT load / leased capacity',10,100,5,'%'],['energyPriceMwh','Variable energy / MWh',0,200,5,'$'],['basePue','Annual PUE',1.05,1.6,.01,'×'],['facilityCapexPerKw','Facility CAPEX / IT kW',5000,22000,50,'$'],['debtPct','Debt share of development',0,80,5,'%'],['interestPct','Debt interest',0,16,.25,'%'],['firstOperationMonth','First phase operating month',24,96,1,'M']];
function economics(){return `<h1 class="page-title">Make the assumptions<br>earn their place.</h1><p class="lede">${P.currency} throughout. Facility lease income and metered energy pass-through are separate. The model includes phased construction, debt drawdown, capitalized interest and 20 operating years. No terminal sale value is assumed.</p><div class="model-layout"><aside class="controls"><h3>Project scenario</h3><p class="small">Scenarios apply to Economics only. Design and delivery pages retain the base case; each project retains its own inputs for this browser session.</p><label class="small" for="scenario">Scenario preset</label><select id="scenario"><option value="custom">Current assumptions</option><option value="base">Base case</option><option value="downside">Cost +20% / rent −15%</option><option value="delay">First operation +12 months</option></select>${fields.map(([key,label,min,max,step,unit])=>`<div class="input-group"><label for="${key}">${label}<output id="out-${key}" for="${key}">${unit==='M'?'M':''}${number(M.inputs[key],step<1?2:0)}${unit==='%'?'%':''}</output></label><input id="${key}" data-input="${key}" type="range" min="${key==='firstOperationMonth'?Math.max(min,M.inputs.constructionMonths+1):min}" max="${key==='basePue'?M.inputs.peakPue:max}" step="${step}" value="${M.inputs[key]}"></div>`).join('')}<div class="actions"><button class="action" id="reset">Reset base case</button><button class="action primary" id="export">Export scenario JSON</button></div></aside><div class="model-results" id="results">${modelResults()}</div></div>`}
function modelResults(){let s=M.steadyState,f=M.finance;let cash=M.cashFlows;return `<div class="metrics">${metric('Total development CAPEX',money(M.capex.totalM),'Excludes finance carry / collateral')}${metric('Stabilized annual EBITDA',money(s.ebitdaM,1),'Pre-tax · before maintenance CAPEX')}${metric('Equity IRR',f.equityIrrPct===null?'No unique IRR':`${number(f.equityIrrPct,1)}%`,'Pre-tax · no terminal sale value')}</div><div class="panel"><h3>Equity cash flow</h3><p class="small">${P.currency} millions · construction through the model horizon. Debt is repaid in the cash-flow model. Terminal property value is zero; refundable utility collateral is returned at the horizon.</p><div class="chart">${chartCash(cash)}</div><div class="legend"><span><i style="background:#bb7952"></i>Equity investment</span><span><i style="background:#39776e"></i>Cash to equity</span></div></div>${heading('01','Capital stack')}${table(['Development cost','Amount'],M.capex.items.map(x=>[E(x.label),money(x.amountM,1)]).concat([['Soft costs',money(M.capex.softCostsM,1)],['Contingency',money(M.capex.contingencyM,1)],['<b>Total development CAPEX</b>',`<b>${money(M.capex.totalM,1)}</b>`],['Construction interest',money(f.constructionInterestM,1)],['Refundable utility collateral',money(f.collateralM,1)],['Total funding requirement',money(f.totalFundingM,1)],['Construction equity',money(f.equityRequiredM,1)],['Maximum cumulative equity deficit',money(f.maximumCumulativeEquityDeficitM,1)],['Gross equity contributions over model horizon',money(f.totalEquityContributionsM,1)],['Debt drawn incl. capitalized carry',money(f.debtDrawnM,1)]]))}${heading('02','Stabilized operating economics')}${table(['Annual item','Amount / volume'],[['Leased IT capacity',`${number(100*M.inputs.occupancyPct/100,1)} MW`],['Average IT demand',`${number(s.itLoadMw,1)} MW`],['Average facility demand',`${number(s.facilityLoadMw,1)} MW`],['Metered facility energy',`${number(s.annualEnergyMwh,0)} MWh`],['Facility lease revenue',money(s.leaseRevenueM,1)],['Energy pass-through revenue',money(s.electricityRevenueM,1)],['Energy expense',money(s.electricityExpenseM,1)],['Fixed OPEX',money(s.fixedOpexM,1)],['Variable OPEX',money(s.variableOpexM,1)],['<b>EBITDA</b>',`<b>${money(s.ebitdaM,1)}</b>`],['Minimum annual operating DSCR',f.minOperatingDscr===null?'Not meaningful / unlevered':`${number(f.minOperatingDscr,2)}×`],['Minimum annual DSCR incl. terminal debt balloon',f.minDscr===null?'Not meaningful / unlevered':`${number(f.minDscr,2)}×`],['Debt balloon at model horizon',money(f.terminalDebtBalloonM,1)],['IRR interpretation',E(f.equityIrrStatus)],['Lease rate for zero equity NPV',`${P.currency} ${number(f.breakEvenLeaseRateKwMonth,0)} / kW / month`],['Equity NPV at '+M.inputs.equityDiscountPct+'%',money(f.equityNpvM,1)],['Customer rent + metered energy',`${P.currency} ${number(M.stabilized.customerAllInKwMonth,0)} / committed kW / month`],['Unlevered project IRR',f.unleveredIrrPct===null?'Undefined':`${number(f.unleveredIrrPct,1)}%`]] )}<div class="callout"><b>Energy costs are not a profit margin</b>Metered electricity expense is passed through at cost. Alberta includes generation CAPEX separately, so its energy input covers variable production/purchased-energy cost; plant fixed operating costs sit in fixed OPEX. Lease economics do not include GPU ownership.</div>${heading('03','Sensitivity to the assumptions')}${table(['Variable','Low / high input','Equity NPV at low / high'],sensitivity(P,edits[region]).map(x=>[E(x.label),`${number(x.low,1)} / ${number(x.high,1)} ${E(x.unit)}`,`${money(x.lowNpvM,1)} / ${money(x.highNpvM,1)}`]))}<details><summary>Annual cash-flow schedule</summary>${table(['Year','End IT MW','CAPEX','EBITDA','Debt service','Equity cash flow'],M.cashFlows.map(x=>[String(x.year),String(x.endOnlineItMw),number(x.capexM,1),number(x.ebitdaM,1),number(x.debtServiceM,1),number(x.equityCashFlowM,1)]))}<p class="small">All cash amounts in ${P.currency} millions. Annual rows reconcile to monthly model timing.</p></details>${heading('04','How the model works')}<div class="formula">IT MWh = 100 MW × occupancy × load factor × 8,760<br>Facility MWh = IT MWh × annual PUE<br>Lease revenue = 100,000 kW × occupancy × rent × 12<br>EBITDA = lease revenue − fixed OPEX − variable OPEX<br>IRR / NPV use timed construction + operating cash flows.</div><details><summary>Full inputs and model boundary</summary>${table(['Input','Value'],Object.entries(M.inputs).map(([k,v])=>[E(k),E(v)]))}${ul(M.exclusions||[])}</details>${(M.warnings||[]).length?`<details open><summary>Scenario qualifications</summary>${ul(M.warnings)}</details>`:''}<div class="actions">${download('base-case.json','Base-case calculations')}${download('model.mjs','Executable model')}${download('model-methodology.md','Model methodology')}</div>`}
function delivery(){let ds=P.delivery;let end=Math.max(...ds.map(x=>x.endMonth));return `<h1 class="page-title">Development is<br>a chain of commitments.</h1><p class="lede">A gated delivery plan from site diligence through integrated commissioning and operations. Month numbers are planning assumptions, not promised calendar dates.</p><div class="phase-strip">${M.phases.map((x,i)=>`<div class="phase"><small>PHASE 0${i+1} / M${x.operationMonth}</small><strong>${(i+1)*25} MW</strong><span class="small">Cumulative IT capacity</span></div>`).join('')}</div><div class="callout"><b>The clock starts only when the stated gates permit it</b>${region==='texas'?'Texas M0 is a future funded restart after regulatory release and route confirmation. Any current permit hold adds an unbounded pre-M0 delay.':'Alberta M0 is the start of funded development, subject to land access and utility/generation process acceptance. Approval and OEM delays can move every operating milestone.'}</div>${heading('01','Execution schedule')}<div class="timeline">${ds.map(x=>`<div class="timeline-row"><span>${E(x.name)}</span><div class="timeline-track"><div class="timeline-bar" style="left:${x.startMonth/end*100}%;width:${(x.endMonth-x.startMonth)/end*100}%">M${x.startMonth}–${x.endMonth}</div></div></div>`).join('')}</div>${table(['Workstream','Dependency','Deliverable / status'],ds.map(x=>[`<b>${E(x.name)}</b>`,E(x.dependency),`${E(x.output)}<br><span class="small">${E(x.status)}</span>`]))}${heading('02','Commercial structure')}<div class="split"><div class="panel"><h3>Offering and contract</h3><p>${E(P.commercial.offering)}</p><p>${E(P.commercial.contracting)}</p></div><div class="panel"><h3>Financing route</h3><p>${E(P.commercial.financing)}</p><p class="small">Financial scenarios are underwriting hypotheses. No customer, lender or investor commitment has been obtained.</p></div></div>${heading('03','Decision gates')}<div class="status-grid">${P.gates.map((x,i)=>`<div class="status-card"><span class="eyebrow">GATE ${String(i+1).padStart(2,'0')} / ${E(x.owner)}</span><h3>${E(x.name)}</h3><p>${E(x.proof)}</p><span class="pill">${E(x.status)}</span></div>`).join('')}</div>${heading('04','Risk register')}${table(['Risk / owner','Impact','Mitigation','Stop / escalate trigger'],P.risks.map(x=>[`<b>${E(x.risk)}</b><br><span class="small">${E(x.owner)}</span>`,E(x.impact),`${E(x.mitigation)} ${refs(x.sourceIds)}`,E(x.trigger)]))}${heading('05','Market entry and counterparties')}<div class="split"><div><h3>Customer development</h3>${ul(P.commercial.goToMarket)}</div><div><h3>Questions that need direct answers</h3>${ul(P.commercial.counterpartyQuestions)}</div></div>${heading('06','Immediate development actions')}<ul class="clean-list numbered">${P.nextActions.map(x=>`<li><span>${E(x)}</span></li>`).join('')}</ul>${heading('07','Execution documents')}<div class="panel"><h3>From equipment release to customer acceptance</h3><p>The execution appendix defines RFQ milestones, measurable commissioning criteria, operating responsibilities, maintenance and spares, customer contract terms, and unsent information requests. Every release remains conditional on its stated evidence gate.</p><div class="actions">${download('execution.md','Editable execution appendix')}${download('delivery-schedule.md','Delivery dependencies')}${download('dossier.pdf','Complete report with execution appendix')}</div></div>`}
function evidence(){return `<h1 class="page-title">Trace every claim.<br>Challenge every estimate.</h1><p class="lede">Sources reviewed ${E(P.asOf)}. Primary records establish what is known; modeled inputs remain estimates unless explicitly documented otherwise.</p><div class="panel"><h3>The complete ${E(P.id==='alberta'?'Alberta':'Texas')} package</h3><p class="small">Independent report, technical drawings, source and assumption registers, project data, calculated base case and executable financial model.</p><div class="actions">${download('project-package.zip','Download complete project')}${download('dossier.pdf','PDF report')}${download('project.json','Project data')}${download('dossier.md','Editable report')}${download('model.mjs','Model source')}${download('execution.md','Execution appendix')}${download('source-register.md','Source register')}</div></div>${heading('01','Assumption register')}${table(['Input','Value / unit','Basis and status','Sources'],P.assumptions.map(x=>[`<b>${E(x.label)}</b><br><span class="small">${E(x.id)}</span>`,`${E(x.value)} ${E(x.unit)}`,`${E(x.basis)}<br><span class="pill">${E(x.status)}</span>`,refs(x.sourceIds)]))}${heading('02',`${P.sources.length} source records`)}<label class="small" for="source-filter">Filter sources by title, claim or publisher</label><input type="search" class="filter" id="source-filter" placeholder="Search the evidence…"><div id="source-list">${sourcesHtml(P.sources)}</div><div class="callout"><b>Evidence boundary</b>Published listings and infrastructure proximity do not establish land availability, transferable capacity, permit eligibility, fibre service, or a construction slot. Accessed dates record this research pass. A planning cost is not a supplier quotation.</div>`}
function sourcesHtml(ss){return ss.length?ss.map(x=>`<article class="source-item" id="${esc(x.id)}"><div class="eyebrow">${E(x.id)}</div><div><h3><a target="_blank" rel="noopener" href="${esc(x.url)}">${E(x.title)} ↗</a></h3><p>${E(x.publisher)} · Published: ${E(x.published)} · Accessed: ${E(x.accessed)}</p><p><b>Supports:</b> ${E(x.claim)}</p><p><b>Limit:</b> ${E(x.limitation)}</p></div></article>`).join(''):'<p class="no-results">No matching sources.</p>'}
function refresh(){P=projects[region];M=calculate(P,section==='economics'?edits[region]:{});ENG=engineering(P,section==='economics'?edits[region]:{})}
function render(){refresh();document.body.className=region;document.title=`${P.region} · 100 MW Development Proposal | Alberta & Texas AI Campuses`;let fn={overview,site,engineering:engineeringView,economics,delivery,evidence}[section];$('#app').innerHTML=`<header class="topbar"><a class="brand" href="?project=${region}" aria-label="Alberta &amp; Texas AI Campuses"><span class="brand-mark">A</span><span>AI campuses<small>Alberta &amp; Texas</small></span></a><div class="project-switch" role="group" aria-label="Select independent project"><button data-project="alberta" class="${region==='alberta'?'active':''}" aria-pressed="${region==='alberta'}">Alberta</button><button data-project="texas" class="${region==='texas'?'active':''}" aria-pressed="${region==='texas'}">Texas</button></div><div class="edition">DEVELOPMENT SERIES / 001–002<br>13 OCTOBER 2026 · CONCEPT REV 01</div></header><div class="shell"><aside class="sidebar"><div class="eyebrow">${E(P.id==='alberta'?'Alberta':'Texas')} / ${P.currency}</div><nav aria-label="Project sections">${views.map(([id,title],i)=>`<button data-view="${id}" class="${section===id?'active':''}" ${section===id?'aria-current="page"':''}><span>0${i+1}</span>${title}</button>`).join('')}</nav><div class="sidebar-foot"><b><i class="dot"></i>100 MW IT / phased build</b>Concept / pre-feasibility<br>Independent development case<br><br><a href="downloads/${region}/project-package.zip" download>Project package ↗</a></div></aside><main id="main"><div class="breadcrumb"><span>Development proposals / ${E(P.id==='alberta'?'Alberta':'Texas')}</span><span>${section.toUpperCase()} · ${section==='economics'?'SCENARIO':'BASE CASE'} · REV 01<br><span id="scenario-note" class="scenario-note">${section==='economics'&&Object.keys(edits[region]).length?'Modified scenario · downloads retain base case':''}</span></span></div>${fn()}<footer class="footer"><span>AI CAMPUSES / ${E(P.region.toUpperCase())} DEVELOPMENT PROPOSAL<br>100 MW IT · local ${P.currency} model · evidence as of ${E(P.asOf)}</span><span>Concept engineering. Unsecured land and capacity.<br>Sources, assumptions and gates are part of the proposal.</span></footer></main></div>`;bind();}
function updateUrl(){let a=new URL(location.href);a.search=`?project=${region}&view=${section}`;a.hash='';history.replaceState({},'',a)}
function go(view){section=view;updateUrl();render();window.scrollTo({top:0,behavior:'instant'})}
function bind(){document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{region=b.dataset.project;updateUrl();render();window.scrollTo(0,0)});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-source]').forEach(a=>a.onclick=ev=>{ev.preventDefault();let id=a.dataset.source;go('evidence');document.getElementById(id)?.scrollIntoView()});document.querySelectorAll('[data-drawing]').forEach(b=>b.onclick=()=>{drawing=b.dataset.drawing;render()});document.querySelectorAll('[data-input]').forEach(input=>input.oninput=()=>{let key=input.dataset.input;edits[region][key]=Number(input.value);refresh();$(`#out-${key}`).textContent=key==='firstOperationMonth'?`M${input.value}`:number(Number(input.value),Number(input.step)<1?2:0)+(key.endsWith('Pct')?'%':'');$('#results').innerHTML=modelResults();$('#scenario').value='custom';$('#scenario-note').textContent='Modified scenario · downloads retain base case';document.querySelectorAll('#results [data-source]').forEach(a=>a.onclick=ev=>{ev.preventDefault();go('evidence')})});if($('#reset'))$('#reset').onclick=()=>{edits[region]={};render()};if($('#scenario'))$('#scenario').onchange=ev=>{let choice=ev.target.value;edits[region]={};if(choice==='downside')edits[region]={facilityCapexPerKw:P.modelOverrides.facilityCapexPerKw*1.2,leaseRateKwMonth:P.modelOverrides.leaseRateKwMonth*.85};if(choice==='delay')edits[region]={firstOperationMonth:P.modelOverrides.firstOperationMonth+12};render();$('#scenario').value=choice};if($('#export'))$('#export').onclick=()=>{let blob=new Blob([JSON.stringify({project:region,asOf:P.asOf,scenarioInputs:M.inputs,results:M,engineering:ENG},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${region}-scenario.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};if($('#source-filter'))$('#source-filter').oninput=ev=>{let term=ev.target.value.toLowerCase();$('#source-list').innerHTML=sourcesHtml(P.sources.filter(x=>JSON.stringify(x).toLowerCase().includes(term)))};}
try{let all=await Promise.all(['alberta','texas'].map(async id=>{let r=await fetch(`data/${id}.json`);if(!r.ok)throw Error(`Project data unavailable (${r.status})`);return [id,await r.json()]}));projects=Object.fromEntries(all);render();if(location.hash)document.getElementById(location.hash.slice(1))?.scrollIntoView();}catch(error){$('#app').innerHTML=`<div class="error"><h1>Project could not load</h1><p>${esc(error.message)}</p><p>Try reloading or use the downloadable project reports.</p></div>`;console.error(error)}
